// Parse the Google Fonts CSS, pull only latin @font-face blocks, download the actual woff2 files
async function getCss(url) {
  const res = await fetch(url, { headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120 Safari/537.36' } });
  return await res.text();
}

function extractLatin(css, family) {
  // split by comment blocks like /* latin */
  const parts = css.split(/\/\*\s*([^*]+?)\s*\*\//);
  const results = []; // {subset, weight, url}
  for (let i = 1; i < parts.length; i += 2) {
    const subset = parts[i].trim();
    const block = parts[i + 1];
    if (subset !== 'latin') continue;
    const wM = block.match(/font-weight:\s*(\d+)/);
    const uM = block.match(/src:\s*url\((https:[^)]+\.woff2)\)/);
    if (wM && uM) results.push({ weight: wM[1], url: uM[1] });
  }
  return results;
}

const manropeCss = await getCss('https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&display=swap');
const interCss = await getCss('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');

const manrope = extractLatin(manropeCss, 'Manrope');
const inter = extractLatin(interCss, 'Inter');
log('manrope', JSON.stringify(manrope, null, 2));
log('inter', JSON.stringify(inter, null, 2));

for (const f of manrope) {
  const r = await fetch(f.url);
  const b = await r.blob();
  await saveFile(`fonts/Manrope-${f.weight}.woff2`, b);
  log(`Manrope-${f.weight}.woff2 ${b.size}`);
}
for (const f of inter) {
  const r = await fetch(f.url);
  const b = await r.blob();
  await saveFile(`fonts/Inter-${f.weight}.woff2`, b);
  log(`Inter-${f.weight}.woff2 ${b.size}`);
}

