/* ==========================================================================
   Trama Design System — Foundation Tokens
   Colors, typography, spacing, radii, elevation.
   Import this file first; everything else builds on these vars.
   ========================================================================== */

/* --- Fonts --------------------------------------------------------------- */
@font-face {
  font-family: 'Manrope';
  font-style: normal;
  font-weight: 400 800;
  font-display: swap;
  src: url('fonts/Manrope-Variable.woff2') format('woff2-variations'),
       url('fonts/Manrope-Variable.woff2') format('woff2');
}
@font-face {
  font-family: 'Inter';
  font-style: normal;
  font-weight: 400 700;
  font-display: swap;
  src: url('fonts/Inter-Variable.woff2') format('woff2-variations'),
       url('fonts/Inter-Variable.woff2') format('woff2');
}

/* --- Light mode tokens (default) ---------------------------------------- */
:root {
  color-scheme: light;

  /* Brand primary */
  --primary:                 #AB2D00;
  --primary-container:       #FF7851;
  --primary-fixed-dim:       #FF5D2B;
  --on-primary:              #FFFFFF;

  /* Surfaces — tonal stack, "paper on stone" */
  --surface:                 #F5F6F7;
  --surface-dim:             #E6E8EA;
  --surface-container-lowest:#FFFFFF;
  --surface-container-low:   #EFF1F2;
  --surface-container:       #E6E8EA;
  --surface-container-high:  #E0E3E4;
  --surface-bright:          #FAFAFA;

  /* Text */
  --on-surface:              #2C2F30;
  --on-surface-variant:      #595C5D;

  /* Accents */
  --secondary-container:     #D7E4EC;
  --outline-variant:          #ABADAE; /* use at 15% opacity max */
  --outline-ghost:           rgba(171, 173, 174, 0.15);

  /* Signature gradient — the ONLY multi-stop gradient allowed */
  --gradient-cta: linear-gradient(135deg, #AB2D00 0%, #FF5D2B 100%);

  /* Ambient shadow — modals and FABs only */
  --shadow-ambient: 0 12px 32px 0 rgba(44, 47, 48, 0.06),
                    0 4px 12px 0 rgba(44, 47, 48, 0.04);
  --shadow-fab:     0 8px 24px 0 rgba(171, 45, 0, 0.18),
                    0 2px 6px  0 rgba(44, 47, 48, 0.08);

  /* Radius scale — no sharp corners */
  --radius-xs: 8px;    /* chips, pills inner */
  --radius-sm: 12px;   /* inputs */
  --radius-md: 16px;   /* small cards, sheets */
  --radius-lg: 24px;   /* standard cards */
  --radius-xl: 32px;   /* hero surfaces */
  --radius-pill: 9999px;

  /* Spacing — 8px vertical rhythm */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-7: 32px;
  --space-8: 40px;
  --space-9: 48px;
  --space-10: 64px;

  /* Glass (top nav + filter chips) */
  --glass-bg:     rgba(245, 246, 247, 0.78);
  --glass-blur:   16px;
}

/* --- Dark mode ----------------------------------------------------------- */
[data-theme='dark'] {
  color-scheme: dark;

  --primary:                 #FF7851;
  --primary-container:       #7A1E00;
  --primary-fixed-dim:       #FF5D2B;
  --on-primary:              #1A0800;

  --surface:                 #111314;
  --surface-dim:             #0C0E0F;
  --surface-container-lowest:#0A0C0D;
  --surface-container-low:   #181B1C;
  --surface-container:       #1E2123;
  --surface-container-high:  #252A2C;
  --surface-bright:          #2C3133;

  --on-surface:              #E2E5E6;
  --on-surface-variant:      #9EA3A5;

  --secondary-container:     #1A2C38;
  --outline-variant:          #3A3F41;
  --outline-ghost:           rgba(58, 63, 65, 0.55);

  /* In dark mode the CTA gradient uses the dark-mode Primary (#FF7851) → Primary Fixed Dim */
  --gradient-cta: linear-gradient(135deg, #FF7851 0%, #FF5D2B 100%);

  --shadow-ambient: 0 16px 40px 0 rgba(0, 0, 0, 0.45),
                    0 4px 12px 0 rgba(0, 0, 0, 0.30);
  --shadow-fab:     0 10px 28px 0 rgba(255, 93, 43, 0.25),
                    0 2px 6px  0 rgba(0, 0, 0, 0.35);

  --glass-bg: rgba(17, 19, 20, 0.72);
}

/* --- Base type ----------------------------------------------------------- */
:root {
  --font-display: 'Manrope', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --font-body:    'Inter',   system-ui, -apple-system, 'Segoe UI', sans-serif;

  /* Scale — matches the written spec exactly */
  --type-display-md:  2.75rem;  /* 44px — Manrope 700 — hero */
  --type-headline-lg: 2rem;     /* 32px — Manrope 600 */
  --type-headline-md: 1.75rem;  /* 28px — Manrope 600 */
  --type-headline-sm: 1.375rem; /* 22px — Manrope 600 — for "Tus conexiones" */
  --type-title-md:    1rem;     /* 16px — Manrope 600, tracking +0.15 */
  --type-body-lg:     1rem;     /* 16px — Inter 400, tracking +0.5 */
  --type-body-md:     0.875rem; /* 14px — Inter 400 */
  --type-body-sm:     0.8125rem;/* 13px — Inter 400 */
  --type-label-sm:    0.75rem;  /* 12px — Inter 500, tracking +0.4 */
}

/* --- Semantic type classes ---------------------------------------------- */
.t-display-md {
  font-family: var(--font-display); font-weight: 700;
  font-size: var(--type-display-md); line-height: 1.08; letter-spacing: -0.02em;
  color: var(--on-surface);
}
.t-headline-lg {
  font-family: var(--font-display); font-weight: 600;
  font-size: var(--type-headline-lg); line-height: 1.15; letter-spacing: -0.015em;
  color: var(--on-surface);
}
.t-headline-md {
  font-family: var(--font-display); font-weight: 600;
  font-size: var(--type-headline-md); line-height: 1.2; letter-spacing: -0.01em;
  color: var(--on-surface);
}
.t-headline-sm {
  font-family: var(--font-display); font-weight: 600;
  font-size: var(--type-headline-sm); line-height: 1.25; letter-spacing: -0.005em;
  color: var(--on-surface);
}
.t-title-md {
  font-family: var(--font-display); font-weight: 600;
  font-size: var(--type-title-md); line-height: 1.3; letter-spacing: 0.15px;
  color: var(--on-surface);
}
.t-body-lg {
  font-family: var(--font-body); font-weight: 400;
  font-size: var(--type-body-lg); line-height: 1.5; letter-spacing: 0.5px;
  color: var(--on-surface);
}
.t-body-md {
  font-family: var(--font-body); font-weight: 400;
  font-size: var(--type-body-md); line-height: 1.5;
  color: var(--on-surface);
}
.t-body-sm {
  font-family: var(--font-body); font-weight: 400;
  font-size: var(--type-body-sm); line-height: 1.45;
  color: var(--on-surface-variant);
}
.t-label-sm {
  font-family: var(--font-body); font-weight: 500;
  font-size: var(--type-label-sm); line-height: 1.3; letter-spacing: 0.4px;
  color: var(--on-surface-variant);
  text-transform: none; /* NOT uppercase — editorial, not institutional-shouty */
}

/* --- Base reset (scoped utility) ---------------------------------------- */
.trama-root {
  background: var(--surface);
  color: var(--on-surface);
  font-family: var(--font-body);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}
.trama-root *, .trama-root *::before, .trama-root *::after { box-sizing: border-box; }

/* --- Network texture (for Surface Dim regions) -------------------------- */
.network-texture {
  background-image:
    radial-gradient(circle at 20% 30%, currentColor 0.8px, transparent 1.2px),
    radial-gradient(circle at 70% 60%, currentColor 0.8px, transparent 1.2px),
    radial-gradient(circle at 40% 80%, currentColor 0.8px, transparent 1.2px);
  background-size: 48px 48px, 72px 72px, 64px 64px;
  color: var(--on-surface);
  opacity: 1;
}
.network-texture::after {
  /* Lines between dots via an SVG data URI for crisp rendering */
  content: '';
  position: absolute; inset: 0;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='120' height='120' viewBox='0 0 120 120'><g stroke='%23000' stroke-width='0.4' fill='none' opacity='0.5'><line x1='24' y1='36' x2='84' y2='72'/><line x1='84' y1='72' x2='48' y2='96'/><line x1='48' y1='96' x2='24' y2='36'/></g></svg>");
  background-size: 120px 120px;
  opacity: 0.04;
  pointer-events: none;
}

/* ==========================================================================
   Trama Mobile UI Kit — screen-level styles
   All component-level styles live in the shared colors_and_type.css.
   This file handles layout (phone frame, nav, cards, screen chrome).
   ========================================================================== */

.phone {
  position: relative;
  width: 390px;
  height: 844px;
  margin: 0 auto;
  background: var(--surface);
  color: var(--on-surface);
  font-family: var(--font-body);
  overflow: hidden;
  border-radius: 48px;
  isolation: isolate;
}
.phone.bezel {
  box-shadow:
    0 0 0 10px #0A0C0D,
    0 0 0 12px #2C3133,
    0 60px 120px -30px rgba(44,47,48,.35);
