/* Status bar (iOS-ish, purely decorative) */
.status-bar {
  position: absolute; top: 0; left: 0; right: 0; height: 54px;
  display: flex; justify-content: space-between; align-items: center;
  padding: 18px 32px 0;
  font: 600 15px/1 'Manrope'; color: var(--on-surface);
  font-feature-settings: "tnum";
  z-index: 50;
  pointer-events: none;
}
.status-bar .icons { display: flex; gap: 6px; align-items: center; }
.status-bar .icons svg { width: 18px; height: 12px; }
.notch {
  position: absolute; top: 11px; left: 50%; transform: translateX(-50%);
  width: 120px; height: 32px; border-radius: 9999px; background: #0A0C0D;
  z-index: 51;
}

/* Home indicator */
.home-indicator {
  position: absolute; bottom: 8px; left: 50%; transform: translateX(-50%);
  width: 134px; height: 5px; border-radius: 9999px; background: var(--on-surface);
  opacity: 0.45; z-index: 60;
}

/* Scroll area */
.screen {
  position: absolute; inset: 0;
  overflow-y: auto;
  overflow-x: hidden;
  background: var(--surface);
}
.screen::-webkit-scrollbar { display: none; }
.screen { scrollbar-width: none; }

/* Top app bar — glassmorphism */
.app-bar {
  position: sticky; top: 0; z-index: 30;
  padding: 54px 24px 12px;
  background: var(--glass-bg);
  backdrop-filter: blur(var(--glass-blur)) saturate(1.2);
  -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(1.2);
}
.app-bar .row { display: flex; gap: 12px; align-items: center; }
.app-bar .title { font: 600 22px/1.2 'Manrope'; color: var(--on-surface); letter-spacing: -0.005em; flex: 1; }
.app-bar .back {
  width: 40px; height: 40px; border-radius: 9999px;
  display: flex; align-items: center; justify-content: center;
  background: var(--surface-container-lowest); color: var(--on-surface);
  border: 0; cursor: pointer;
}
.app-bar .search {
  flex: 1;
  background: var(--surface-container-lowest);
