}
.bottom-nav .tab svg { width: 24px; height: 24px; stroke-width: 1.5; }
.bottom-nav .tab.active { color: var(--primary); }
.bottom-nav .tab .lbl { opacity: 0; height: 0; transition: opacity .2s, height .2s; }
.bottom-nav .tab.active .lbl { opacity: 1; height: auto; }

/* Floating action button */
.fab {
  position: absolute; right: 20px; bottom: 96px; z-index: 35;
  width: 56px; height: 56px; border-radius: 9999px; border: 0;
  background: var(--gradient-cta); color: var(--on-primary);
