/* Buttons (reused) */
.btn {
  font: 600 15px/1 'Manrope'; padding: 14px 22px; border-radius: 9999px;
  border: 0; cursor: pointer; letter-spacing: 0.15px;
  transition: background .2s, transform .15s;
}
.btn.primary { background: var(--gradient-cta); color: var(--on-primary); }
.btn.secondary { background: var(--surface-container-high); color: var(--on-surface); }
