// ============================================================================
// Trama Mobile UI Kit — shared building-block components (JSX, plain React)
// Each component reads tokens from colors_and_type.css + ui_kit.css.
// No external UI libs. Lucide icons via CDN (window.lucide.*).
// ============================================================================

const { useState, useEffect, useMemo } = React;

// ----- Icon wrapper ---------------------------------------------------------
function Icon({ name, size = 24, stroke = 1.5, ...rest }) {
  // Use lucide's createIcons approach: render an <i data-lucide> that lucide replaces,
  // OR use the inline createElement API when available.
  const ref = React.useRef(null);
  useEffect(() => {
    if (window.lucide && ref.current) window.lucide.createIcons({ nameAttr: 'data-lucide', attrs: { 'stroke-width': stroke, width: size, height: size }, icons: window.lucide.icons, parent: ref.current.parentNode });
  }, [name, stroke, size]);
  return <i ref={ref} data-lucide={name} style={{ width: size, height: size, display: 'inline-flex' }} {...rest} />;
}

// ----- Phone chrome --------------------------------------------------------
function PhoneFrame({ theme = 'light', bezel = true, children }) {
  return (
    <div className={"trama-root phone" + (bezel ? ' bezel' : '')} data-theme={theme}>
      <div className="notch" />
      <div className="status-bar">
        <span>9:41</span>
        <span className="icons">
          <svg viewBox="0 0 18 12" fill="none"><path d="M1 10 L1 8 M4 10 L4 6 M7 10 L7 4 M10 10 L10 2" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round"/></svg>
          <svg viewBox="0 0 18 12" fill="none"><path d="M2 2 Q9 -2 16 2 M4 5 Q9 2 14 5 M6 8 Q9 6 12 8" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" fill="none"/></svg>
          <svg viewBox="0 0 22 12" fill="none"><rect x="1" y="2" width="17" height="8" rx="2" stroke="currentColor" strokeWidth="1" fill="none"/><rect x="2.5" y="3.5" width="11" height="5" rx="1" fill="currentColor"/><rect x="19" y="5" width="2" height="2" rx="0.5" fill="currentColor"/></svg>
        </span>
      </div>
      {children}
      <div className="home-indicator" />
    </div>
  );
}

// ----- Bottom nav ----------------------------------------------------------
function BottomNav({ active = 'discover', onChange = () => {} }) {
  const tabs = [
    { id: 'discover', icon: 'compass',      label: 'Descubrir' },
    { id: 'matches',  icon: 'users-round',  label: 'Conexiones' },
    { id: 'groups',   icon: 'book-open',    label: 'Grupos' },
    { id: 'profile',  icon: 'user-round',   label: 'Perfil' },
  ];
  return (
    <nav className="bottom-nav">
      {tabs.map(t => (
        <button key={t.id} className={"tab" + (active === t.id ? ' active' : '')} onClick={() => onChange(t.id)}>
          <Icon name={t.icon} stroke={active === t.id ? 2 : 1.5}/>
          <span className="lbl">{t.label}</span>
        </button>
      ))}
    </nav>
  );
}

// ----- Score bars ----------------------------------------------------------
function ScoreBar({ role, pct, variant = 'academic' }) {
  return (
    <div className={"score-block " + variant}>
      <div className="top">
        <span className="role">{role}</span>
        <span className="pct">{pct}%</span>
      </div>
      <div className="track"><div className="fill" style={{ width: pct + '%' }}/></div>
    </div>
  );
}

// ----- Chip ----------------------------------------------------------------
function Chip({ children, selected, onClick, variant, size }) {
  const cls = ['chip'];
  if (selected) cls.push('selected');
  if (variant === 'filter') cls.push('filter');
  if (variant === 'filter-active') cls.push('filter', 'active');
  if (size === 'sm') cls.push('small');
  return <button className={cls.join(' ')} onClick={onClick}>{children}</button>;
}

// ----- Semester badge ------------------------------------------------------
function SemesterBadge({ n }) {
  return <span className="sem-badge">{n}° semestre</span>;
}

// ----- Avatar (initials placeholder) --------------------------------------
function Avatar({ name, size = 'md', hue = 0 }) {
  const initials = name.split(' ').slice(0, 2).map(s => s[0]).join('').toUpperCase();
  // Deterministic soft pastel background from hue
  const bg = `linear-gradient(135deg, oklch(88% 0.04 ${hue}), oklch(72% 0.05 ${(hue+40)%360}))`;
  return (
    <div className={"avatar" + (size === 'lg' ? ' lg' : '')} style={{ background: bg }}>
      {initials}
    </div>
  );
}

// ----- Student card (Discovery list) --------------------------------------
function StudentCard({ s, onOpen }) {
  return (
    <div className="student-card" onClick={onOpen} role="button" tabIndex={0}>
      <div>
        <div className="head">
          <div className="name">{s.name}</div>
          <div className="program">{s.program}</div>
        </div>
        <div className="chip-row">
          <SemesterBadge n={s.semester}/>
          {s.interests.slice(0, 2).map(i => <Chip key={i} size="sm">{i}</Chip>)}
        </div>
        <div className="scores">
          <ScoreBar role="Match académico" pct={s.academic} variant="academic"/>
          <ScoreBar role="Match personal"  pct={s.personal} variant="personal"/>
        </div>
      </div>
      <div className="photo" style={{ background: `linear-gradient(160deg, oklch(82% 0.04 ${s.hue}) 0%, oklch(55% 0.10 ${(s.hue+30)%360}) 100%)` }}/>
    </div>
  );
}

// ----- Connection row (Matches screen) ------------------------------------
function ConnectionCard({ c }) {
  return (
    <div className="conn-card">
      <Avatar name={c.name} hue={c.hue}/>
      <div>
        <div className="ctx">{c.context}</div>
        <div className="name">{c.name}</div>
        <div className="summary">{c.summary}</div>
      </div>
      <div className="time">{c.time}</div>
    </div>
  );
}

