// Personal Interests — Onboarding Step 3/4
const { useState } = React;
function PersonalScreen() {
  const OPTIONS = ['Yoga', 'Cine de autor', 'Fotografía', 'Senderismo', 'Café de especialidad', 'Lectura', 'Debate', 'Voluntariado', 'Música en vivo', 'Teatro', 'Ciclismo', 'Cocina', 'Idiomas', 'Viajes', 'Ajedrez', 'Escritura creativa'];
  const [picks, setPicks] = useState(new Set(['Cine de autor', 'Fotografía', 'Senderismo', 'Lectura']));
  const toggle = (i) => { const s = new Set(picks); s.has(i) ? s.delete(i) : s.add(i); setPicks(s); };
  return (
    <PhoneFrame theme="light">
      <div className="screen" style={{ paddingBottom: 120 }}>
        <div style={{ padding: '118px 24px 32px', background: 'var(--surface-dim)', position: 'relative', overflow: 'hidden' }}>
