          <div className="step-dots" style={{ marginBottom: 24, position: 'relative' }}>
            <div className="dot done"/><div className="dot done"/><div className="dot active"/><div className="dot"/>
          </div>
          <div style={{ position: 'relative' }}>
            <div className="t-label-sm" style={{ color: 'var(--primary)', marginBottom: 8 }}>Paso 3 de 4 · Intereses personales</div>
            <h1 className="t-headline-lg" style={{ margin: 0, maxWidth: 300 }}>¿Qué haces fuera del aula?</h1>
            <p className="t-body-md" style={{ margin: '12px 0 0', color: 'var(--on-surface-variant)', maxWidth: 320 }}>
              Tus intereses personales complementan el match académico. Elige al menos 3.
            </p>
          </div>
        </div>
        <div style={{ padding: 24 }}>
          <div className="t-label-sm" style={{ marginBottom: 12 }}>{picks.size} seleccionados</div>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
            {OPTIONS.map(o => <Chip key={o} selected={picks.has(o)} onClick={() => toggle(o)} size="sm">{o}</Chip>)}
          </div>
        </div>
      </div>
      <div style={{ position: 'absolute', left: 0, right: 0, bottom: 0, padding: '16px 24px 28px', background: 'var(--surface-container-low)', zIndex: 40, display: 'flex', gap: 12 }}>
        <button className="btn ghost" style={{ flex: '0 0 auto' }}>Atrás</button>
        <button className="btn primary" style={{ flex: 1 }}>Continuar</button>
      </div>
    </PhoneFrame>
  );
}
