.btn.primary { background: var(--gradient-cta); color: var(--on-primary); }
.btn.secondary { background: var(--surface-container-high); color: var(--on-surface); }
.btn.ghost { background: transparent; color: var(--primary); }
.btn:active { transform: scale(0.98); }
.btn.full { width: 100%; justify-content: center; display: flex; }

/* Card */
.card {
  background: var(--surface-container-lowest);
  border-radius: 24px;
  padding: 20px;
}

/* Chips */
.chip {
  font: 500 13px/1 'Inter'; padding: 9px 14px; border-radius: 9999px;
  letter-spacing: 0.1px; white-space: nowrap;
  background: var(--secondary-container); color: var(--on-surface-variant);
  border: 0; cursor: pointer;
}
.chip.selected { background: var(--primary); color: var(--on-primary); }
.chip.filter {
  background: var(--surface-container-lowest); color: var(--on-surface);
  padding: 8px 14px; font-size: 12px;
}
.chip.filter.active { background: var(--on-surface); color: var(--surface-container-lowest); }
.chip.small { font-size: 11px; padding: 6px 10px; }

/* Score bars */
.score-block { display: flex; flex-direction: column; gap: 6px; }
.score-block .top { display: flex; justify-content: space-between; align-items: baseline; }
.score-block .role { font: 500 11px/1 'Inter'; color: var(--on-surface-variant); letter-spacing: 0.4px; }
.score-block .pct  { font: 600 13px/1 'Manrope'; color: var(--on-surface); font-feature-settings: "tnum"; }
.score-block .track { height: 6px; background: var(--surface-container-high); border-radius: 9999px; overflow: hidden; }
.score-block .fill  { height: 100%; border-radius: 9999px; }
.score-block.academic .fill { background: var(--gradient-cta); }
.score-block.personal .fill { background: var(--primary); opacity: 0.85; }

/* Input */
.field { display: flex; flex-direction: column; gap: 8px; }
.field label { font: 500 12px/1.3 'Inter'; color: var(--on-surface-variant); letter-spacing: 0.4px; }
.field .input {
  background: var(--surface-container-high); border: 0; border-radius: 12px;
  padding: 14px 16px; font: 400 15px/1.2 'Inter'; color: var(--on-surface); outline: none;
  width: 100%;
}
.field .input:focus { box-shadow: 0 0 0 2px rgba(171,45,0,0.4); background: var(--surface-container-lowest); }
.field .stepper {
  display: flex; align-items: center; justify-content: space-between;
  background: var(--surface-container-high); border-radius: 12px; padding: 6px 6px 6px 16px;
}
.field .stepper .val { font: 600 16px/1 'Manrope'; color: var(--on-surface); }
.field .stepper button {
  width: 40px; height: 40px; border-radius: 9999px; border: 0;
  background: var(--surface-container-lowest); color: var(--on-surface);
  cursor: pointer; font: 600 18px/1 'Manrope';
}

/* Progress dots (onboarding) */
.step-dots { display: flex; gap: 6px; }
.step-dots .dot { width: 28px; height: 4px; border-radius: 9999px; background: var(--surface-container-high); }
.step-dots .dot.done { background: var(--primary); opacity: 0.55; }
.step-dots .dot.active { background: var(--primary); }

/* Avatar */
.avatar {
  width: 48px; height: 48px; border-radius: 50%;
  background: linear-gradient(135deg, #D7E4EC, #ABADAE);
  flex-shrink: 0; overflow: hidden; display: flex; align-items: center; justify-content: center;
  color: var(--on-surface); font: 600 16px/1 'Manrope';
}
.avatar.lg { width: 64px; height: 64px; font-size: 22px; }

/* Student card — Discovery list */
.student-card {
  background: var(--surface-container-lowest);
  border-radius: 24px;
  padding: 20px 20px 20px 20px;
  display: grid;
  grid-template-columns: 1fr 96px;
  gap: 16px;
  align-items: stretch;
  overflow: hidden;
  position: relative;
}
.student-card .head { display: flex; flex-direction: column; gap: 4px; }
.student-card .name { font: 600 17px/1.2 'Manrope'; color: var(--on-surface); letter-spacing: -0.005em; }
.student-card .program { font: 400 13px/1.3 'Inter'; color: var(--on-surface-variant); }
.student-card .chip-row { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 8px; }
.student-card .scores { display: flex; flex-direction: column; gap: 10px; margin-top: 14px; }
.student-card .photo {
  width: 96px;
  align-self: stretch;
  min-height: 100%;
  background: linear-gradient(180deg, #D7E4EC, #ABADAE);
  border-radius: 16px;
  margin-right: -20px;
  background-size: cover;
  background-position: center;
}

/* Section header inside scroll */
.section-header {
  padding: 24px 24px 12px;
}
.section-header h2 {
  margin: 0; font: 600 15px/1 'Manrope'; color: var(--on-surface-variant);
  letter-spacing: 0.2px;
}

/* Connection row (Matches screen) */
.conn-card {
  background: var(--surface-container-lowest);
  border-radius: 20px; padding: 16px;
  display: grid; grid-template-columns: 56px 1fr auto; gap: 14px;
  align-items: center;
}
.conn-card .ctx {
  font: 500 11px/1 'Inter'; color: var(--primary); letter-spacing: 0.3px;
  margin-bottom: 6px;
}
.conn-card .name { font: 600 15px/1.2 'Manrope'; color: var(--on-surface); }
.conn-card .summary { font: 400 12px/1.3 'Inter'; color: var(--on-surface-variant); margin-top: 2px; }
.conn-card .time { font: 500 11px/1 'Inter'; color: var(--on-surface-variant); letter-spacing: 0.3px; white-space: nowrap; }

/* Schedule grid (profile availability) */
.schedule {
  display: grid; grid-template-columns: 36px repeat(7, 1fr); gap: 4px;
  margin-top: 12px;
}
.schedule .col-h { font: 500 10px/1 'Inter'; color: var(--on-surface-variant); text-align: center; letter-spacing: 0.3px; padding-bottom: 4px; }
.schedule .row-h { font: 500 10px/1 'Inter'; color: var(--on-surface-variant); text-align: right; padding-right: 6px; align-self: center; }
.schedule .cell { height: 20px; border-radius: 4px; background: var(--surface-container-high); }
.schedule .cell.busy { background: var(--primary); opacity: 0.85; }
.schedule .cell.maybe { background: var(--primary); opacity: 0.35; }

/* Profile hero */
.profile-hero {
  position: relative; height: 320px; background: #ABADAE;
}
.profile-hero .back {
  position: absolute; top: 52px; left: 16px;
  width: 40px; height: 40px; border-radius: 9999px;
  background: var(--glass-bg); backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  display: flex; align-items: center; justify-content: center;
  color: var(--on-surface); border: 0; cursor: pointer; z-index: 5;
}
.profile-hero .overlay {
  position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 40%, var(--surface) 100%);
}
.profile-hero .name-block {
  position: absolute; left: 24px; right: 24px; bottom: 20px; z-index: 3;
}
.profile-hero .name { font: 700 28px/1.1 'Manrope'; color: var(--on-surface); letter-spacing: -0.01em; }
.profile-hero .program-row { display: flex; gap: 6px; margin-top: 10px; }

/* Empty state */
.empty {
  text-align: left; padding: 40px 24px 24px; display: flex; flex-direction: column; gap: 16px;
}
.empty svg { width: 160px; height: auto; color: var(--on-surface-variant); opacity: 0.55; }
.empty h3 { margin: 0; font: 600 22px/1.2 'Manrope'; color: var(--on-surface); letter-spacing: -0.005em; }
.empty p  { margin: 0; font: 400 14px/1.5 'Inter'; color: var(--on-surface-variant); max-width: 300px; }

/* Semester badge */
.sem-badge {
  display: inline-flex; align-items: center; gap: 4px;
  font: 500 11px/1 'Inter'; padding: 6px 10px; border-radius: 9999px;
  background: var(--secondary-container); color: var(--on-surface-variant);
  letter-spacing: 0.3px;
}

/* ---------------- Additional screens ---------------- */

/* Messaging list + conversation */
.msg-row {
  display: grid; grid-template-columns: 56px 1fr auto; gap: 14px;
  padding: 14px 24px; align-items: center; cursor: pointer;
}
.msg-row:hover { background: var(--surface-container-low); }
.msg-row .name { font: 600 15px/1.2 'Manrope'; color: var(--on-surface); }
.msg-row .preview { font: 400 13px/1.3 'Inter'; color: var(--on-surface-variant); margin-top: 3px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 200px; }
.msg-row .meta { display: flex; flex-direction: column; align-items: flex-end; gap: 6px; }
.msg-row .time { font: 500 11px/1 'Inter'; color: var(--on-surface-variant); letter-spacing: 0.2px; }
.msg-row .unread { width: 18px; height: 18px; border-radius: 9999px; background: var(--primary); color: var(--on-primary); font: 600 10px/18px 'Manrope'; text-align: center; font-feature-settings: "tnum"; }

.bubble-row { display: flex; margin: 8px 24px; max-width: 320px; }
.bubble-row.mine { margin-left: auto; justify-content: flex-end; }
.bubble {
  padding: 12px 16px; border-radius: 20px;
  font: 400 14px/1.4 'Inter'; max-width: 260px;
  background: var(--surface-container-lowest); color: var(--on-surface);
}
.bubble-row.mine .bubble { background: var(--gradient-cta); color: var(--on-primary); border-bottom-right-radius: 6px; }
.bubble-row.theirs .bubble { border-bottom-left-radius: 6px; }
.bubble-time { font: 500 10px/1 'Inter'; color: var(--on-surface-variant); letter-spacing: 0.3px; padding: 0 24px; margin-top: 4px; }
.bubble-time.mine { text-align: right; }

.composer {
  position: absolute; left: 0; right: 0; bottom: 0;
  padding: 14px 20px 28px;
  background: var(--glass-bg);
  backdrop-filter: blur(var(--glass-blur)) saturate(1.2);
  -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(1.2);
  display: flex; gap: 10px; align-items: center; z-index: 40;
}
.composer .input {
  flex: 1; background: var(--surface-container-lowest);
  border-radius: 9999px; padding: 12px 18px;
  font: 400 14px/1.2 'Inter'; color: var(--on-surface-variant);
}
.composer .send {
  width: 44px; height: 44px; border-radius: 9999px; border: 0;
  background: var(--gradient-cta); color: var(--on-primary);
  display: flex; align-items: center; justify-content: center; cursor: pointer;
}

.context-banner {
  margin: 16px 24px 0; padding: 10px 14px; border-radius: 12px;
  background: var(--secondary-container); color: var(--on-surface-variant);
  font: 500 12px/1.4 'Inter'; display: flex; gap: 10px; align-items: center;
}

/* Groups */
.group-card {
  background: var(--surface-container-lowest);
  border-radius: 24px; padding: 20px;
  display: flex; flex-direction: column; gap: 12px;
}
.group-card .header { display: flex; align-items: center; gap: 12px; }
.group-card .glyph { width: 48px; height: 48px; border-radius: 14px; display: flex; align-items: center; justify-content: center; background: var(--secondary-container); color: var(--on-surface); }
.group-card .title { font: 600 16px/1.2 'Manrope'; color: var(--on-surface); letter-spacing: -0.005em; }
.group-card .sub   { font: 400 12px/1.3 'Inter'; color: var(--on-surface-variant); margin-top: 4px; }
.group-card .desc  { font: 400 13px/1.5 'Inter'; color: var(--on-surface); }
.group-card .foot  { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.avatar-stack { display: flex; }
.avatar-stack .avatar { width: 28px; height: 28px; font-size: 11px; border: 2px solid var(--surface-container-lowest); }
.avatar-stack .avatar + .avatar { margin-left: -10px; }
.avatar-stack .more { background: var(--surface-container-high); color: var(--on-surface-variant); }

/* Own profile */
.my-stat-row { display: flex; gap: 12px; margin: 0 24px; }
.my-stat-row .stat { flex: 1; padding: 16px; border-radius: 16px; background: var(--surface-container-lowest); }
.my-stat-row .n { font: 700 22px/1 'Manrope'; color: var(--on-surface); letter-spacing: -0.01em; font-feature-settings: "tnum"; }
.my-stat-row .lbl { font: 500 11px/1.3 'Inter'; color: var(--on-surface-variant); margin-top: 6px; letter-spacing: 0.3px; }

.settings-list { background: var(--surface-container-lowest); border-radius: 20px; margin: 0 24px; overflow: hidden; }
.settings-row { padding: 16px 20px; display: flex; align-items: center; gap: 14px; cursor: pointer; }
.settings-row + .settings-row { box-shadow: 0 -1px 0 var(--outline-ghost); } /* felt divider — ghost border */
.settings-row:hover { background: var(--surface-bright); }
.settings-row .label { flex: 1; font: 500 14px/1.2 'Manrope'; color: var(--on-surface); }
.settings-row .val { font: 400 13px/1 'Inter'; color: var(--on-surface-variant); }

/* Notifications */
.notif-row {
  padding: 16px 24px; display: grid; grid-template-columns: 40px 1fr auto;
  gap: 14px; align-items: flex-start;
}
.notif-row.unread { background: color-mix(in oklab, var(--primary) 6%, transparent); }
.notif-row .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--primary); margin-top: 8px; }
.notif-row .dot.read { background: transparent; }
.notif-row .title { font: 600 14px/1.3 'Manrope'; color: var(--on-surface); }
.notif-row .body { font: 400 13px/1.4 'Inter'; color: var(--on-surface-variant); margin-top: 4px; }
.notif-row .time { font: 500 11px/1 'Inter'; color: var(--on-surface-variant); letter-spacing: 0.2px; white-space: nowrap; }
.notif-row .glyph { width: 40px; height: 40px; border-radius: 12px; display: flex; align-items: center; justify-content: center; background: var(--secondary-container); color: var(--on-surface); }
.notif-row.match .glyph { background: var(--gradient-cta); color: var(--on-primary); }

