  const p = `ui_kits/mobile/${f}`;
  let t = await readFile(p);
  // Onboarding/Personal/Welcome hero blocks used 118px or 80px top padding
  t = t.replace(/padding: '118px /g, "padding: '80px ");
  t = t.replace(/padding: '80px 24px 32px'/g, "padding: '80px 24px 32px'"); // no-op preserve
  await saveFile(p, t);
  log('updated', f);
}

