.auth-hero h1 { font: 700 28px/1.15 'Manrope'; margin: 0; letter-spacing: -0.015em; max-width: 280px; color: var(--on-surface); }
.auth-hero p  { font: 400 14px/1.5 'Inter'; margin: 8px 0 0; color: var(--on-surface-variant); max-width: 280px; }

.auth-form { padding: 24px 24px 32px; display: flex; flex-direction: column; gap: 16px; }
.auth-form .meta-link { font: 500 13px/1 'Inter'; color: var(--primary); cursor: pointer; align-self: flex-end; padding: 4px 4px; min-height: 32px; display: inline-flex; align-items: center; }
